}   public decimal FinalPrice
        { 
            get
            {
                var today = DateTime.Today;
                var firstDayThisMonth = new DateTime(today.Year, today.Month, 1);
                var firstDayPrevMonth = firstDayThisMonth.AddMonths(-1);
